"""Rejection-corpus generator (v0: tests/data vectors only; no RPC).

Parses the FCMP++ verify-input vectors (monero binary serialization), applies
structured mutations, and writes corpus cases + a manifest. Expected verdicts
are left null here; the oracle stage (stock binary over RPC, or block-path
injection) fills them. A case whose oracle verdict is ACCEPT goes to the
must-accept companion set, not the rejection corpus.

Usage:
  corpus_generator.py gen  <vectors_dir> <out_dir> [n_cases]
  corpus_generator.py check <out_dir> <fork_verdicts.json>

Written 2026-11-08."""
import hashlib
import json
import os
import random
import struct
import sys


def parse_vector(blob: bytes):
    i = 0

    def take(n):
        nonlocal i
        v = blob[i:i + n]
        i += n
        return v

    def varint():
        nonlocal i
        res, shift = 0, 0
        while True:
            b = blob[i]
            i += 1
            res |= (b & 0x7F) << shift
            if not b & 0x80:
                return res
            shift += 7

    signable = take(32)
    layers = take(1)
    proof = take(varint())
    root = take(32)
    n = varint()
    pseudo = [take(32) for _ in range(n)]
    n = varint()
    kis = [take(32) for _ in range(n)]
    assert i == len(blob), "trailing bytes"
    return {
        "signable": bytearray(signable), "layers": bytearray(layers),
        "proof": bytearray(proof), "root": bytearray(root),
        "pseudo": [bytearray(p) for p in pseudo],
        "key_images": [bytearray(k) for k in kis],
    }


def ser_vector(v) -> bytes:
    def varint_enc(x):
        out = bytearray()
        while True:
            b = x & 0x7F
            x >>= 7
            out.append(b | (0x80 if x else 0))
            if not x:
                return out

    out = bytearray()
    out += v["signable"]
    out += v["layers"]
    out += varint_enc(len(v["proof"]))
    out += v["proof"]
    out += v["root"]
    out += varint_enc(len(v["pseudo"]))
    for p in v["pseudo"]:
        out += p
    out += varint_enc(len(v["key_images"]))
    for k in v["key_images"]:
        out += k
    return bytes(out)


def sal_len(v):
    return len(v["pseudo"]) * ((3 * 32) + (12 * 32))


def mutate(v, rng):
    """Return (mutated_copy, description)."""
    import copy
    m = copy.deepcopy(v)
    n_in = len(m["pseudo"])
    sal = sal_len(m)
    op = rng.randrange(9)
    if op == 0:  # single-bit flip in SAL region
        pos = rng.randrange(sal)
        m["proof"][pos] ^= 1 << rng.randrange(8)
        d = f"sal-bitflip@{pos}"
    elif op == 1:  # single-bit flip in FCMP region
        pos = sal + rng.randrange(len(m["proof"]) - sal)
        m["proof"][pos] ^= 1 << rng.randrange(8)
        d = f"fcmp-bitflip@{pos}"
    elif op == 2:  # multi-byte (2-4) in FCMP region
        for _ in range(rng.randrange(2, 5)):
            pos = sal + rng.randrange(len(m["proof"]) - sal)
            m["proof"][pos] ^= 1 << rng.randrange(8)
        d = "fcmp-multibit"
    elif op == 3:  # key image byte
        ki = rng.randrange(n_in)
        pos = rng.randrange(32)
        m["key_images"][ki][pos] ^= 1 << rng.randrange(8)
        d = f"keyimage{ki}-bitflip@{pos}"
    elif op == 4:  # pseudo-out byte
        po = rng.randrange(n_in)
        pos = rng.randrange(32)
        m["pseudo"][po][pos] ^= 1 << rng.randrange(8)
        d = f"pseudoout{po}-bitflip@{pos}"
    elif op == 5:  # tree root byte
        m["root"][rng.randrange(32)] ^= 1 << rng.randrange(8)
        d = "root-bitflip"
    elif op == 6:  # signable hash byte
        m["signable"][rng.randrange(32)] ^= 1 << rng.randrange(8)
        d = "signablehash-bitflip"
    elif op == 7:  # layers lie (+/-1)
        old = m["layers"][0]
        m["layers"][0] = max(1, old + rng.choice([-1, 1]))
        d = f"layers {old}->{m['layers'][0]}"
    else:  # key image swap (statement mismatch with valid parts)
        if n_in >= 2:
            a, b = rng.sample(range(n_in), 2)
            m["key_images"][a], m["key_images"][b] = m["key_images"][b], m["key_images"][a]
            d = f"keyimage-swap {a}<->{b}"
        else:
            m["proof"][sal] ^= 1
            d = "fcmp-bitflip@sal0"
    return m, d


def main():
    if len(sys.argv) < 4:
        print(__doc__)
        sys.exit(1)
    mode, vectors_dir, out_dir = sys.argv[1], sys.argv[2], sys.argv[3]
    if mode == "gen":
        n_target = int(sys.argv[4]) if len(sys.argv) > 4 else 2000
        rng = random.Random(0x6D6E65746F)  # deterministic corpus
        vectors = {}
        for name in sorted(os.listdir(vectors_dir)):
            if name.startswith("fcmp_pp_verify_inputs_") and name.endswith(".bin"):
                with open(os.path.join(vectors_dir, name), "rb") as f:
                    vectors[name] = parse_vector(f.read())
        assert vectors, "no vectors found"
        os.makedirs(out_dir, exist_ok=True)
        cases = []
        n = 0
        names = list(vectors)
        while n < n_target:
            src = names[n % len(names)]
            m, desc = mutate(vectors[src], rng)
            blob = ser_vector(m)
            cid = f"case{n:05d}"
            path = os.path.join(out_dir, cid + ".bin")
            with open(path, "wb") as f:
                f.write(blob)
            cases.append({
                "id": cid,
                "source": src,
                "mutation": desc,
                "sha256": hashlib.sha256(blob).hexdigest(),
                "expected_verdict": None,  # filled by the oracle stage
            })
            n += 1
        # must-accept set: the unmodified vectors
        accept = []
        for name, v in vectors.items():
            blob = ser_vector(v)
            aid = "accept-" + name.replace("fcmp_pp_verify_inputs_", "").replace(".bin", "")
            with open(os.path.join(out_dir, aid + ".bin"), "wb") as f:
                f.write(blob)
            accept.append({"id": aid, "sha256": hashlib.sha256(blob).hexdigest(),
                           "expected_verdict": "accept"})
        manifest = {
            "generator": "corpus_generator.py v0",
            "seed": 0x6D6E65746F,
            "cases": cases,
            "must_accept": accept,
        }
        with open(os.path.join(out_dir, "manifest.json"), "w") as f:
            json.dump(manifest, f, indent=1)
        print(f"wrote {len(cases)} rejection cases + {len(accept)} must-accept to {out_dir}")
    elif mode == "check":
        with open(os.path.join(out_dir, "manifest.json")) as f:
            manifest = json.load(f)
        with open(sys.argv[4]) as f:
            verdicts = json.load(f)  # {case_id: "accept"|"reject", ...}
        bad = 0
        for c in manifest["cases"] + manifest["must_accept"]:
            got = verdicts.get(c["id"])
            if c["expected_verdict"] is None:
                continue
            if got != c["expected_verdict"]:
                print(f"VERDICT MISMATCH {c['id']}: expected {c['expected_verdict']} got {got}")
                bad += 1
        print(f"check: {bad} mismatches")
        sys.exit(1 if bad else 0)
    else:
        print(__doc__)
        sys.exit(1)


if __name__ == "__main__":
    main()
